locals {
  infra_dashboards = {
    gke               = { title = "GKE Cluster & Workloads" }
    cloud-run         = { title = "Cloud Run" }
    compute-databases = { title = "Compute Engine & Databases" }
    # Pendientes (Plan 08-03 iterativo):
    # load-balancer = { title = "Load Balancers" }
    # shared-infra  = { title = "Shared Infrastructure" }
  }
}

resource "grafana_dashboard" "infra" {
  for_each  = local.infra_dashboards
  folder    = grafana_folder.infra.uid
  overwrite = true

  config_json = templatefile("${path.module}/dashboards/${each.key}.json", {
    datasource_uid = local.datasource_uid_monitoring
  })
}

content.content:
resource "grafana_data_source" "cloud_monitoring" {
  type = "stackdriver"
  name = "Google Cloud Monitoring"
  uid  = local.datasource_uid_monitoring

  json_data_encoded = jsonencode({
    authenticationType = "jwt"
    defaultProject     = "prod-apps-454414"
    clientEmail        = jsondecode(data.sops_file.secrets.data["grafana_monitoring_sa_json"]).client_email
    tokenUri           = "https://oauth2.googleapis.com/token"
  })

  secure_json_data_encoded = jsonencode({
    privateKey = jsondecode(data.sops_file.secrets.data["grafana_monitoring_sa_json"]).private_key
  })
}

# Google Managed Prometheus datasources via frontend proxies (Phase 8-02b).
# Each proxy runs as a Docker container in the observability VM and maps to one
# GCP project. Grafana reaches them via the internal Docker network.
locals {
  gmp_datasources = {
    qa = {
      name = "GMP-qa"
      uid  = "gmp-qa"
      url  = "http://gmp-frontend-qa:9090"
    }
    staging = {
      name = "GMP-staging"
      uid  = "gmp-staging"
      url  = "http://gmp-frontend-staging:9090"
    }
    prod = {
      name = "GMP-prod"
      uid  = "gmp-prod"
      url  = "http://gmp-frontend-prod:9090"
    }
    sec = {
      name = "GMP-sec"
      uid  = "gmp-sec"
      url  = "http://gmp-frontend-sec:9090"
    }
    sha = {
      name = "GMP-shared"
      uid  = "gmp-sha"
      url  = "http://gmp-frontend-sha:9090"
    }
    bi = {
      name = "GMP-bi"
      uid  = "gmp-bi"
      url  = "http://gmp-frontend-bi:9090"
    }
  }
}

resource "grafana_data_source" "gmp" {
  for_each = local.gmp_datasources
  type     = "prometheus"
  name     = each.value.name
  uid      = each.value.uid
  url      = each.value.url

  json_data_encoded = jsonencode({
    httpMethod     = "POST"
    timeInterval   = "30s"
    prometheusType = "Prometheus"
  })
}

